package com.alpharip.staffmod.AuditFindingsBoard;
import net.minecraft.client.gui.*;import java.io.IOException;import java.util.List;
/** Initial in-game queue. A real StaffMods authorization adapter is required before use. */
public final class AuditFindingsGui extends GuiScreen {
 private static final int ADD=1,BACK=2,CATEGORY=3,SEVERITY=4,ROW=1000,REMOVE=2000;
 private final GuiScreen parent;private final AuditFindingsController controller;private GuiTextField title,description,owner;private int left,top,right,bottom,scroll,cat,sev;private String message="LOCAL PROTOTYPE";
 private final AuditFindingCategory[] categories=AuditFindingCategory.values();private final AuditFindingSeverity[] severities=AuditFindingSeverity.values();
 public AuditFindingsGui(GuiScreen parent,AuditFindingsController c){if(c==null)throw new IllegalArgumentException("Controller required");this.parent=parent;controller=c;}
 @Override public void initGui(){controller.load();buttonList.clear();int w=Math.min(580,width-20),h=Math.min(410,height-20);left=(width-w)/2;right=left+w;top=(height-h)/2;bottom=top+h;title=new GuiTextField(10,fontRendererObj,left+14,top+54,w-28,18);description=new GuiTextField(11,fontRendererObj,left+14,top+92,w-28,18);owner=new GuiTextField(12,fontRendererObj,left+14,top+130,w-28,18);title.setMaxStringLength(100);description.setMaxStringLength(240);owner.setMaxStringLength(32);
  if(controller.getAccess().canManageFindings()){buttonList.add(new GuiButton(ADD,right-116,top+162,102,20,"ADD FINDING"));buttonList.add(new GuiButton(CATEGORY,left+14,top+162,140,20,"CATEGORY: "+categories[cat].name()));buttonList.add(new GuiButton(SEVERITY,left+160,top+162,140,20,"SEVERITY: "+severities[sev].name()));}buttonList.add(new GuiButton(BACK,left+14,bottom-27,70,20,"BACK"));rows();}
 private void rows(){for(int i=buttonList.size()-1;i>=0;i--)if(buttonList.get(i).id>=ROW)buttonList.remove(i);if(!controller.getAccess().canViewFindings())return;List<AuditFinding> all=controller.getRegistry().getAll();int visible=Math.max(1,(bottom-top-250)/29);scroll=Math.max(0,Math.min(scroll,all.size()-visible));for(int i=scroll;i<Math.min(all.size(),scroll+visible);i++){int row=i-scroll,y=top+224+row*29;if(controller.getAccess().canManageFindings()){buttonList.add(new GuiButton(ROW+row,right-126,y,58,18,"STATUS"));buttonList.add(new GuiButton(REMOVE+row,right-64,y,52,18,"REMOVE"));}}}
 @Override public void drawScreen(int mx,int my,float partial){drawDefaultBackground();drawRect(left,top,right,bottom,0xF00D1017);drawRect(left,top,right,top+2,0xFFFFD866);drawCenteredString(fontRendererObj,"AUDIT FINDINGS BOARD",width/2,top+13,0xFFF3F4F6);drawCenteredString(fontRendererObj,"STAFF OPERATIONS · LOCAL PROTOTYPE",width/2,top+29,0xFFFFD866);drawString(fontRendererObj,"TITLE",left+14,top+43,0xFFB8BDC8);title.drawTextBox();drawString(fontRendererObj,"DESCRIPTION",left+14,top+81,0xFFB8BDC8);description.drawTextBox();drawString(fontRendererObj,"OWNER / ASSIGNEE",left+14,top+119,0xFFB8BDC8);owner.drawTextBox();AuditFindingsSummary s=new AuditFindingsService(controller.getRegistry()).summarize(System.currentTimeMillis());drawString(fontRendererObj,"TOTAL "+s.getTotal()+"  OPEN "+s.getOpen()+"  REVIEW "+s.getInReview()+"  CRITICAL "+s.getCritical()+"  OVERDUE "+s.getOverdue(),left+14,top+194,0xFFB8BDC8);List<AuditFinding> all=controller.getRegistry().getAll();int visible=Math.max(1,(bottom-top-250)/29);if(all.isEmpty())drawCenteredString(fontRendererObj,"No findings recorded",width/2,top+235,0xFFB8BDC8);for(int i=scroll;i<Math.min(all.size(),scroll+visible);i++){AuditFinding f=all.get(i);int y=top+224+(i-scroll)*29;drawRect(left+12,y,right-12,y+25,0xAA191D25);String line=f.getTitle()+" · "+f.getSeverity().name()+" · "+f.getStatus().name()+" · "+(f.getOwner().isEmpty()?"UNASSIGNED":f.getOwner());drawString(fontRendererObj,fontRendererObj.trimStringToWidth(line,right-left-170),left+20,y+8,color(f.getSeverity()));}drawString(fontRendererObj,message,left+100,bottom-23,0xFFB8BDC8);super.drawScreen(mx,my,partial);}
 private int color(AuditFindingSeverity s){switch(s){case CRITICAL:return 0xFFFF7777;case HIGH:return 0xFFFFB45C;case MEDIUM:return 0xFFFFD866;case LOW:return 0xFF9CE2AC;default:return 0xFFB8BDC8;}}
 @Override protected void actionPerformed(GuiButton b)throws IOException{if(b.id==BACK){mc.displayGuiScreen(parent);return;}if(b.id==CATEGORY){cat=(cat+1)%categories.length;b.displayString="CATEGORY: "+categories[cat].name();return;}if(b.id==SEVERITY){sev=(sev+1)%severities.length;b.displayString="SEVERITY: "+severities[sev].name();return;}if(b.id==ADD){try{controller.getService().create(title.getText(),description.getText(),categories[cat],severities[sev],owner.getText(),0L,System.currentTimeMillis());controller.save();title.setText("");description.setText("");owner.setText("");message="Finding added";rows();}catch(RuntimeException e){message=e.getMessage();}return;}if(b.id>=ROW&&b.id<REMOVE){if(!controller.getAccess().canManageFindings())return;int i=scroll+b.id-ROW;List<AuditFinding> all=controller.getRegistry().getAll();if(i<all.size()){AuditFinding f=all.get(i);AuditFindingStatus[] states=AuditFindingStatus.values();controller.getService().setStatus(f.getId(),states[(f.getStatus().ordinal()+1)%states.length],"",System.currentTimeMillis());controller.save();message="Status updated";}rows();return;}if(b.id>=REMOVE){if(!controller.getAccess().canManageFindings())return;int i=scroll+b.id-REMOVE;List<AuditFinding> all=controller.getRegistry().getAll();if(i<all.size())controller.getService().remove(all.get(i).getId());controller.save();message="Finding removed";rows();}}
 @Override protected void mouseClicked(int x,int y,int button)throws IOException{title.mouseClicked(x,y,button);description.mouseClicked(x,y,button);owner.mouseClicked(x,y,button);super.mouseClicked(x,y,button);}
 @Override protected void keyTyped(char c,int key)throws IOException{if(key==1){mc.displayGuiScreen(parent);return;}title.textboxKeyTyped(c,key);description.textboxKeyTyped(c,key);owner.textboxKeyTyped(c,key);super.keyTyped(c,key);}
 @Override public boolean doesGuiPauseGame(){return false;}
}
